import org.joda.time.chrono.ISOChronology;
import org.joda.time.convert.ConverterManager;
import org.joda.time.convert.PeriodConverter;
import org.joda.time.field.FieldUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for BasePeriod(long duration) constructor.
 * Since the constructor is protected, we use a Test subclass to access it.
 */
public class BasePeriod_BasePeriod_TriageGen1Test {

    /**
     * Concrete implementation of BasePeriod to allow testing of the protected constructor.
     */
    private static class TestBasePeriod extends BasePeriod {
        protected TestBasePeriod(long duration) {
            super(duration);
        }

        protected TestBasePeriod(long duration, PeriodType type, org.joda.time.chrono.Chronology chrono) {
            super(duration, type, chrono);
        }
    }

    @Test
    public void testConstructorWithPositiveDuration() {
        long durationMillis = 3600000L; // 1 hour
        TestBasePeriod period = new TestBasePeriod(durationMillis);

        assertNotNull("Period should not be null", period);
        // Since the constructor calls this(duration, null, null), 
        // it should initialize with default PeriodType and ISOChronology
        assertEquals("PeriodType should be default", PeriodType.standard(), period.getPeriodType());
    }

    @Test
    public void testConstructorWithZeroDuration() {
        long durationMillis = 0L;
        TestBasePeriod period = new TestBasePeriod(durationMillis);

        assertNotNull(period);
        assertEquals("PeriodType should be default", PeriodType.standard(), period.getPeriodType());
    }

    @Test
    public void testConstructorWithNegativeDuration() {
        long durationMillis = -3600000L;
        TestBasePeriod period = new TestBasePeriod(durationMillis);

        assertNotNull(period);
        // Joda-time periods can represent negative durations
        assertEquals("PeriodType should be default", PeriodType.standard(), period.getPeriodType());
    }

    @Test
    public void testConstructorWithLongMaxValue() {
        long durationMillis = Long.MAX_VALUE;
        TestBasePeriod period = new TestBasePeriod(durationMillis);

        assertNotNull(period);
        assertEquals("PeriodType should be default", PeriodType.standard(), period.getPeriodType());
    }

    @Test
    public void testConstructorWithLongMinValue() {
        long durationMillis = Long.MIN_VALUE;
        TestBasePeriod period = new TestBasePeriod(durationMillis);

        assertNotNull(period);
        assertEquals("PeriodType should be default", PeriodType.standard(), period.getPeriodType());
    }
}
